const money = (value?: number) => {
  if (value == null) return '—';
  if (Math.abs(value) >= 10_000_000) return `₹${(value / 10_000_000).toFixed(1)} Cr`;
  return `₹${(value / 100_000).toFixed(0)} L`;
};
const moneyFull = (value?: number) => value == null ? '—' : `₹${value.toLocaleString('en-IN')}`;
const pct = (value?: number) => value == null ? '—' : `${value.toFixed(0)}%`;
const likelihoodPct = (value?: number) => value == null ? '—' : `${(value * 100).toFixed(1)}%`;
const dateTime = (value?: string) => {
  if (!value) return 'Awaiting sync';
  const parsed = new Date(value);
  return Number.isNaN(parsed.getTime()) ? value : parsed.toLocaleString([], { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' });
};
const severityClass = (severity = '') => severity.toLowerCase().includes('critical') ? 'severity-critical' : severity.toLowerCase().includes('high') ? 'severity-high' : severity.toLowerCase().includes('medium') ? 'severity-medium' : 'severity-low';

function Skeleton({ className = '' }: { className?: string }) {
  return <div className={`animate-pulse rounded-md bg-slate-200/70 dark:bg-slate-700/60 ${className}`} />;
}

function EmptyState({ title, detail, action }: { title: string; detail: string; action?: ReactNode }) {
  return <div className="flex min-h-[260px] flex-col items-center justify-center rounded-xl border border-dashed border-border bg-card/60 px-6 text-center">
    <div className="mb-4 rounded-xl bg-secondary p-3 text-muted-foreground"><Inbox size={22} /></div>
    <h3 className="text-sm font-bold">{title}</h3>
    <p className="mt-1 max-w-sm text-xs leading-5 text-muted-foreground">{detail}</p>
    {action && <div className="mt-4">{action}</div>}
  </div>;
}

function ErrorState({ retry, detail = 'The model endpoint did not respond. The cockpit will keep trying when you refresh.' }: { retry?: () => void; detail?: string }) {
  return <div className="flex min-h-[220px] flex-col items-center justify-center rounded-xl border border-destructive/25 bg-destructive/5 px-6 text-center">
    <CircleAlert size={22} className="text-destructive" />
    <h3 className="mt-3 text-sm font-bold">Signal unavailable</h3>
    <p className="mt-1 max-w-sm text-xs leading-5 text-muted-foreground">{detail}</p>
    {retry && <button data-testid="button-retry" onClick={retry} className="mt-4 inline-flex items-center gap-2 rounded-md border border-border bg-card px-3 py-2 text-xs font-bold hover:border-primary"><RefreshCw size={13} /> Retry connection</button>}
  </div>;
}

function PageHeader({ eyebrow, title, detail, action }: { eyebrow: string; title: string; detail: string; action?: ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 md:flex-row md:items-end">
    <div>
      <div className="mb-2 flex items-center gap-2 text-[10px] font-bold uppercase tracking-[.2em] text-muted-foreground"><span className="h-1.5 w-1.5 rounded-full bg-accent" /> {eyebrow}</div>
      <h1 className="text-2xl font-extrabold tracking-[-.04em] md:text-3xl">{title}</h1>
      <p className="mt-2 max-w-2xl text-sm text-muted-foreground">{detail}</p>
    </div>
    {action}
  </div>;
}

function MetricCard({ label, value, detail, trend, accent = false, testId }: { label: string; value: string; detail?: string; trend?: number; accent?: boolean; testId: string }) {
  return <div data-testid={testId} className={`relative overflow-hidden rounded-xl border p-4 ${accent ? 'border-primary/30 bg-primary text-primary-foreground' : 'border-card-border bg-card'}`}>
    <div className="flex items-start justify-between gap-3"><span className={`text-[10px] font-bold uppercase tracking-[.15em] ${accent ? 'text-primary-foreground/70' : 'text-muted-foreground'}`}>{label}</span>{trend != null && <span className={`flex items-center gap-0.5 text-[11px] font-bold ${trend > 0 ? (accent ? 'text-primary-foreground' : 'text-destructive') : (accent ? 'text-accent' : 'text-emerald-700')}`}>{trend > 0 ? <ArrowUpRight size={12} /> : <ArrowDownRight size={12} />}{Math.abs(trend).toFixed(1)}%</span>}</div>
    <div className={`mt-3 font-mono-ui text-2xl font-medium tracking-[-.05em] ${accent ? 'text-primary-foreground' : 'text-foreground'}`}>{value}</div>
    {detail && <div className={`mt-2 text-[11px] ${accent ? 'text-primary-foreground/65' : 'text-muted-foreground'}`}>{detail}</div>}
    {accent && <div className="absolute -right-6 -top-8 h-28 w-28 rounded-full border-[12px] border-accent/20" />}
  </div>;
}

function SectionCard({ title, eyebrow, action, children, className = '' }: { title: string; eyebrow?: string; action?: ReactNode; children: ReactNode; className?: string }) {
  return <section className={`rounded-xl border border-card-border bg-card ${className}`}>
    <div className="flex items-center justify-between border-b border-border px-4 py-3.5">
      <div><div className="text-[10px] font-bold uppercase tracking-[.16em] text-muted-foreground">{eyebrow}</div><h2 className="mt-0.5 text-sm font-extrabold">{title}</h2></div>
      {action}
    </div>
    <div className="p-4">{children}</div>
  </section>;
}

function Sparkline({ points, color = 'hsl(var(--accent))' }: { points: number[]; color?: string }) {
  const max = Math.max(...points, 1); const min = Math.min(...points, 0); const span = max - min || 1;
  const d = points.map((point, index) => `${index ? 'L' : 'M'} ${(index / Math.max(points.length - 1, 1)) * 100} ${94 - ((point - min) / span) * 78}`).join(' ');
  return <svg viewBox="0 0 100 100" preserveAspectRatio="none" className="h-16 w-full overflow-visible"><path d={`${d} L 100 100 L 0 100 Z`} fill={color} opacity=".1" /><path d={d} fill="none" stroke={color} strokeWidth="2.5" vectorEffect="non-scaling-stroke" /></svg>;
}

