          {!collapsed && <div className="mb-2 px-3 text-[9px] font-bold uppercase tracking-[.19em] text-sidebar-foreground/45">{group.label}</div>}
          {group.items.map(({ href, label, icon: Icon }) => <Link href={href} key={href} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`} onClick={() => setMobileOpen(false)} className={`group mb-1 flex items-center gap-3 rounded-lg px-3 py-2.5 text-[12px] font-semibold ${location === href ? 'bg-sidebar-accent text-accent' : 'text-sidebar-foreground/65 hover:bg-sidebar-accent hover:text-sidebar-foreground'}`}>
            <Icon size={16} strokeWidth={location === href ? 2.5 : 1.8} /><span className={collapsed ? 'sr-only' : ''}>{label}</span>{location === href && !collapsed && <ChevronRight size={13} className="ml-auto opacity-60" />}
          </Link>)}
