function OverviewPage() {
  const overview = useGetOverview();
  const drivers = useGetRiskDrivers();
  const trends = useGetRiskTrends();
  const incidents = useGetIncidents();
  const threats = useGetThreats();
  const ingest = useIngestEvent();
  const qc = useQueryClient();
  const [ingested, setIngested] = useState<{ before: number; after: number; driver: string } | null>(null);
  const data = overview.data; const enterprise = data?.enterprise;
  const trendPoints = trends.data?.map(t => t.eal) ?? [];
  const runEvent = () => ingest.mutate({ data: { type: 'critical_vulnerability', assetId: 'payments-api', severity: 'critical' } }, { onSuccess: (result) => { setIngested({ before: result.ealBefore, after: result.ealAfter, driver: result.driver.name }); qc.invalidateQueries({ queryKey: getGetOverviewQueryKey() }); qc.invalidateQueries({ queryKey: getGetRiskDriversQueryKey() }); qc.invalidateQueries({ queryKey: getGetRiskTrendsQueryKey() }); } });
  return <div className="animate-rise">
    <PageHeader eyebrow="Executive cockpit · live model" title="Risk, in the language of capital." detail="NovaBank Financial Services · A live view of modeled exposure, the drivers behind it, and the decisions that reduce it." action={<div className="flex items-center gap-2 text-[10px] text-muted-foreground"><span className="font-mono-ui">LAST SYNC</span> {dateTime(data?.lastUpdated)} <RefreshCw size={12} className={overview.isFetching ? 'animate-spin' : ''} /></div>} />
    {overview.isLoading ? <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5">{Array.from({ length: 5 }).map((_, i) => <Skeleton key={i} className="h-28" />)}</div> : overview.isError ? <ErrorState retry={() => overview.refetch()} /> : <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5">
      <MetricCard testId="metric-enterprise-eal" label="Enterprise EAL" value={money(enterprise?.eal)} detail="Expected annual loss" trend={enterprise?.delta ? (enterprise.delta / 82_000_000) * 100 : 0} accent />
      <MetricCard testId="metric-var95" label="VaR 95" value={money(enterprise?.var95)} detail="One-year confidence bound" />
      <MetricCard testId="metric-cvar95" label="CVaR 95" value={money(enterprise?.cvar95)} detail="Tail exposure" />
      <MetricCard testId="metric-risk-score" label="Risk score" value={`${enterprise?.riskScore ?? '—'}/100`} detail={`${likelihoodPct(enterprise?.likelihood)} modeled likelihood`} trend={enterprise?.delta ? (enterprise.delta / 82_000_000) * 100 : 0} />
      <MetricCard testId="metric-control-effectiveness" label="Control effectiveness" value={pct(data?.controlEffectiveness)} detail={`${data?.criticalAssets ?? '—'} critical assets`} />
    </div>}
    <div className="mt-4 grid gap-4 lg:grid-cols-[1.55fr_1fr]">
      <SectionCard title="Exposure trajectory" eyebrow="Financial signal · trailing model" action={<Link href="/risk" data-testid="link-view-risk" className="flex items-center gap-1 text-[11px] font-bold text-primary hover:text-accent">Open analysis <ChevronRight size={13} /></Link>}>
        {trendPoints.length ? <><div className="mb-4 flex items-end justify-between"><div><div className="font-mono-ui text-xl font-medium">{money(enterprise?.eal)}</div><div className="mt-1 text-[11px] text-muted-foreground">Modeled EAL · 12-week movement</div></div><div className="rounded-md bg-emerald-600/10 px-2 py-1 text-[10px] font-bold text-emerald-700">↓ 8.4% vs prior period</div></div><Sparkline points={trendPoints} /><div className="mt-2 flex justify-between text-[9px] text-muted-foreground"><span>{trends.data?.[0]?.label}</span><span>Now</span></div></> : <EmptyState title="Awaiting trend signal" detail="Connect a source or refresh the model to see exposure movement." />}
      </SectionCard>
      <SectionCard title="Top exposure drivers" eyebrow="Why the number moves" action={<Link href="/risk" data-testid="link-drivers" className="text-[11px] font-bold text-primary">View all</Link>}>
        <div className="space-y-4">{drivers.isLoading ? Array.from({ length: 3 }).map((_, i) => <Skeleton key={i} className="h-9" />) : drivers.data?.slice(0, 4).map((driver, i) => <DriverRow key={driver.id} driver={driver} rank={i + 1} />)}</div>
      </SectionCard>
    </div>
    <div className="mt-4 grid gap-4 lg:grid-cols-[1.1fr_1fr_1fr]">
      <SectionCard title="Trigger the model" eyebrow="Demo event ingestion" className="grid-signal">
        <div className="flex h-full flex-col justify-between gap-5"><div><div className="flex items-center gap-2 text-sm font-bold"><TriangleAlert size={16} className="text-destructive" /> Simulate critical vulnerability</div><p className="mt-2 text-xs leading-5 text-muted-foreground">Inject an event against Payments API to watch EAL and the leading driver recalculate.</p></div>{ingested && <div className="rounded-lg border border-accent/30 bg-accent/10 p-3 text-[11px]"><div className="font-bold text-accent-foreground">Model recalculated</div><div className="mt-1 text-muted-foreground">{moneyFull(ingested.before)} → <span className="font-bold text-foreground">{moneyFull(ingested.after)}</span> · Driver: {ingested.driver}</div></div>}<button data-testid="button-ingest-critical-event" disabled={ingest.isPending} onClick={runEvent} className="flex w-full items-center justify-center gap-2 rounded-lg bg-primary px-3 py-2.5 text-xs font-bold text-primary-foreground hover:bg-primary/90 disabled:opacity-60">{ingest.isPending ? <Loader2 size={14} className="animate-spin" /> : <Play size={14} />} {ingest.isPending ? 'Recalculating…' : 'Run simulated event'}</button></div>
      </SectionCard>
      <SectionCard title="Recent incidents" eyebrow="Loss signal" action={<Link href="/risk" data-testid="link-incidents" className="text-[11px] font-bold text-primary">Inspect</Link>}>
        {incidents.data?.length ? <div className="space-y-3">{incidents.data.slice(0, 3).map(incident => <div key={incident.id} className="flex items-start justify-between gap-3 text-xs"><div><div className="font-bold">{incident.type}</div><div className="mt-0.5 text-[10px] text-muted-foreground">{incident.asset} · {dateTime(incident.date)}</div></div><div className="text-right"><div className="font-mono-ui font-medium">{money(incident.totalLoss)}</div><span className={`text-[9px] font-bold uppercase ${severityClass(incident.severity)}`}>{incident.severity}</span></div></div>)}</div> : <EmptyState title="No realized incidents" detail="The model has not received a loss event in this window." />}
      </SectionCard>
      <SectionCard title="Threat pulse" eyebrow="External pressure">
        {threats.data?.length ? <div className="space-y-3">{threats.data.slice(0, 3).map(threat => <div key={threat.id} className="flex items-center gap-3"><div className="h-8 w-8 rounded-md bg-secondary p-2"><Activity size={14} className="text-accent-foreground" /></div><div className="min-w-0 flex-1"><div className="truncate text-xs font-bold">{threat.name}</div><div className="text-[10px] text-muted-foreground">{threat.targetSector} · activity {threat.activityLevel}/100</div></div><div className="h-1.5 w-14 overflow-hidden rounded-full bg-secondary"><div className="h-full rounded-full bg-accent" style={{ width: `${threat.activityLevel}%` }} /></div></div>)}</div> : <EmptyState title="Quiet perimeter" detail="No active threat intelligence signal." />}
      </SectionCard>
    </div>
    <div className="mt-5 flex items-start gap-2 rounded-lg border border-border bg-secondary/35 px-3 py-2.5 text-[10px] leading-4 text-muted-foreground"><Info size={13} className="mt-0.5 shrink-0" /><span><strong className="text-foreground">Synthetic model caveat:</strong> EAL, VaR, likelihood, and risk scores are modeled estimates derived from simulated telemetry. They are decision-support signals, not realized loss or a guarantee of future outcomes.</span></div>
  </div>;
}

function DriverRow({ driver, rank }: { driver: RiskDriver; rank: number }) {
  return <div data-testid={`row-driver-${driver.id}`} className="group flex items-center gap-3"><div className="font-mono-ui text-[10px] text-muted-foreground">0{rank}</div><div className="min-w-0 flex-1"><div className="flex items-center justify-between gap-2"><span className="truncate text-xs font-bold">{driver.name}</span><span className="font-mono-ui text-[11px]">{money(driver.contribution)}</span></div><div className="mt-1 h-1 overflow-hidden rounded-full bg-secondary"><div className="h-full rounded-full bg-accent" style={{ width: `${Math.min(driver.share, 100)}%` }} /></div><div className="mt-1 text-[10px] text-muted-foreground">{pct(driver.share)} of modeled EAL · {driver.affectedAssets} affected assets</div></div></div>;
}

function RiskPage() {
  const enterprise = useGetEnterpriseRisk(); const business = useGetBusinessUnitRisk(); const services = useGetServiceRisk(); const drivers = useGetRiskDrivers(); const trends = useGetRiskTrends(); const assets = useRiskAssets();
  return <div className="animate-rise"><PageHeader eyebrow="Risk intelligence" title="What is carrying the exposure?" detail="Decompose enterprise risk by business unit, service, and financial driver. Every row is a path to a decision." action={<Link href="/simulations" data-testid="link-risk-to-simulations" className="flex items-center gap-2 rounded-lg bg-primary px-3 py-2.5 text-xs font-bold text-primary-foreground hover:bg-primary/90"><SlidersHorizontal size={14} /> Model a mitigation</Link>} />
    <div className="grid gap-3 sm:grid-cols-3"><MetricCard testId="metric-risk-page-eal" label="Enterprise EAL" value={money(enterprise.data?.eal)} detail="Current modeled baseline" accent /><MetricCard testId="metric-risk-page-score" label="Risk score" value={`${enterprise.data?.riskScore ?? '—'}/100`} detail="Composite exposure index" /><MetricCard testId="metric-risk-page-events" label="Events modeled" value={enterprise.data?.eventCount?.toLocaleString() ?? '—'} detail="Telemetry observations" /></div>
    <div className="mt-4 grid gap-4 lg:grid-cols-[1.2fr_1fr]"><SectionCard title="Driver stack" eyebrow="Ranked by EAL contribution" action={<span className="font-mono-ui text-[10px] text-muted-foreground">{drivers.data?.length ?? 0} drivers</span>}>{drivers.isLoading ? <Skeleton className="h-52" /> : drivers.data?.length ? <div className="space-y-5">{drivers.data.map((driver, i) => <DriverRow key={driver.id} driver={driver} rank={i + 1} />)}</div> : <EmptyState title="No drivers mapped" detail="Risk drivers will appear once telemetry is modeled." />}</SectionCard><SectionCard title="Risk movement" eyebrow="Modeled EAL across the last 12 weeks">{trends.data?.length ? <><Sparkline points={trends.data.map(item => item.eal)} color="hsl(var(--chart-2))" /><div className="mt-3 grid grid-cols-3 gap-2">{trends.data.slice(-3).map(item => <div key={item.label} className="rounded-md bg-secondary p-2"><div className="text-[9px] text-muted-foreground">{item.label}</div><div className="mt-1 font-mono-ui text-xs">{money(item.eal)}</div></div>)}</div></> : <EmptyState title="No trend signal" detail="Historical movement needs a connected model." />}</SectionCard></div>
    <div className="mt-4 grid gap-4 lg:grid-cols-2"><SectionCard title="Business unit exposure" eyebrow="Concentration by operating group">{business.data?.length ? <div className="divide-y divide-border">{business.data.map(unit => <div key={unit.id} className="flex items-center gap-4 py-3 first:pt-0 last:pb-0"><div className="flex h-8 w-8 items-center justify-center rounded-lg bg-secondary text-xs font-bold text-primary">{unit.name.slice(0, 2).toUpperCase()}</div><div className="min-w-0 flex-1"><div className="text-xs font-bold">{unit.name}</div><div className="mt-1 text-[10px] text-muted-foreground">{unit.assetCount} assets · {unit.criticalAssets} critical</div></div><div className="w-28"><div className="flex justify-between text-[10px]"><span className="font-mono-ui">{money(unit.eal)}</span><span className="text-muted-foreground">{unit.riskScore}/100</span></div><div className="mt-1 h-1 overflow-hidden rounded bg-secondary"><div className="h-full bg-accent" style={{ width: `${unit.riskScore}%` }} /></div></div></div>)}</div> : <EmptyState title="No business units" detail="Business unit roll-ups are waiting for the API." />}</SectionCard><SectionCard title="Services with highest exposure" eyebrow="Operational concentration">{services.data?.length ? <div className="grid gap-2 sm:grid-cols-2">{services.data.slice(0, 6).map(service => <div key={service.id} className="rounded-lg border border-border p-3"><div className="flex items-start justify-between gap-2"><div><div className="text-xs font-bold">{service.name}</div><div className="mt-1 text-[10px] text-muted-foreground">{service.businessUnit}</div></div><span className={`rounded px-1.5 py-1 text-[9px] font-bold ${service.criticality > 7 ? 'bg-destructive/10 text-destructive' : 'bg-accent/20 text-accent-foreground'}`}>C{service.criticality}</span></div><div className="mt-4 flex items-baseline justify-between"><span className="font-mono-ui text-sm">{money(service.eal)}</span><span className="text-[10px] text-muted-foreground">{service.riskScore}/100 score</span></div></div>)}</div> : <EmptyState title="No service map" detail="Service data is not available." />}</SectionCard></div>
    <SectionCard title="Highest-risk assets" eyebrow="Risk-ranked inventory" className="mt-4" action={<Link href="/assets" data-testid="link-risk-assets" className="text-[11px] font-bold text-primary">Open inventory</Link>}>{assets.data?.length ? <AssetTable assets={assets.data.slice(0, 5)} compact /> : <EmptyState title="No assets ranked" detail="Asset risk will populate from the inventory endpoint." />}</SectionCard>
  </div>;
}

function AssetTable({ assets, compact = false }: { assets: AssetRisk[]; compact?: boolean }) {
  return <div className="overflow-x-auto"><table className="w-full min-w-[680px] text-left"><thead><tr className="border-b border-border text-[9px] font-bold uppercase tracking-wider text-muted-foreground"><th className="pb-2 pl-1">Asset</th><th className="pb-2">Business unit</th><th className="pb-2">Criticality</th><th className="pb-2">EAL</th><th className="pb-2">Likelihood</th><th className="pb-2">Control</th><th /></tr></thead><tbody className="text-xs">{assets.map(asset => <tr key={asset.id} data-testid={`row-asset-${asset.id}`} className="group border-b border-border/70 last:border-0"><td className="py-3 pl-1"><Link href={`/assets/${asset.id}`} data-testid={`link-asset-${asset.id}`} className="flex items-center gap-2 font-bold hover:text-primary"><span className="flex h-7 w-7 items-center justify-center rounded-md bg-secondary"><CloudCog size={14} /></span><span><span className="block">{asset.name}</span><span className="mt-0.5 block text-[10px] font-normal text-muted-foreground">{asset.service} · {asset.assetType}</span></span></Link></td><td className="py-3 text-muted-foreground">{asset.businessUnit}</td><td className="py-3"><span className={`rounded px-1.5 py-1 text-[10px] font-bold ${asset.criticality >= 90 ? 'bg-destructive/10 text-destructive' : 'bg-accent/20 text-accent-foreground'}`}>{asset.criticality}/100</span></td><td className="py-3 font-mono-ui">{money(asset.eal)}</td><td className="py-3 font-mono-ui">{likelihoodPct(asset.likelihood)}</td><td className="py-3"><div className="flex items-center gap-2"><div className="h-1 w-12 overflow-hidden rounded bg-secondary"><div className="h-full bg-emerald-600" style={{ width: `${asset.controlEffectiveness}%` }} /></div><span className="font-mono-ui text-[10px]">{pct(asset.controlEffectiveness)}</span></div></td><td className="py-3 text-right"><ChevronRight size={14} className="text-muted-foreground opacity-0 transition-opacity group-hover:opacity-100" /></td></tr>)}</tbody></table></div>;
}

function AssetsPage() {
  const assets = useGetAssets(); const [search, setSearch] = useState(''); const [filter, setFilter] = useState('all');
  const filtered = useMemo(() => (assets.data ?? []).filter(asset => `${asset.name} ${asset.service} ${asset.businessUnit}`.toLowerCase().includes(search.toLowerCase())).filter(asset => filter === 'all' || asset.severity.toLowerCase() === filter), [assets.data, search, filter]);
  return <div className="animate-rise"><PageHeader eyebrow="Asset intelligence" title="Every crown jewel, ranked." detail="Search the inventory by operational context, then drill into the controls and recommendations shaping its EAL." action={<div className="flex items-center gap-2 text-[10px] text-muted-foreground"><span className="font-mono-ui">{assets.data?.length ?? 0}</span> assets modeled</div>} />
    <SectionCard title="Asset inventory" eyebrow="Risk-ranked operational surface" action={<div className="flex items-center gap-2"><button data-testid="button-filter-all-assets" onClick={() => setFilter('all')} className={`rounded-md px-2 py-1 text-[10px] font-bold ${filter === 'all' ? 'bg-primary text-primary-foreground' : 'bg-secondary text-muted-foreground'}`}>All</button><button data-testid="button-filter-critical-assets" onClick={() => setFilter('critical')} className={`rounded-md px-2 py-1 text-[10px] font-bold ${filter === 'critical' ? 'bg-destructive text-destructive-foreground' : 'bg-secondary text-muted-foreground'}`}>Critical</button></div>}>
      <div className="mb-4 flex flex-col gap-2 sm:flex-row"><label className="relative flex-1"><Search size={14} className="absolute left-3 top-2.5 text-muted-foreground" /><input data-testid="input-search-assets" value={search} onChange={e => setSearch(e.target.value)} placeholder="Search asset, service, or business unit" className="w-full rounded-lg border border-input bg-background py-2 pl-9 pr-3 text-xs outline-none focus:border-primary focus:ring-2 focus:ring-primary/15" /></label><button data-testid="button-refresh-assets" onClick={() => assets.refetch()} className="inline-flex items-center justify-center gap-2 rounded-lg border border-input px-3 py-2 text-xs font-bold hover:bg-secondary"><RefreshCw size={13} className={assets.isFetching ? 'animate-spin' : ''} /> Refresh</button></div>
      {assets.isLoading ? <Skeleton className="h-72" /> : assets.isError ? <ErrorState retry={() => assets.refetch()} /> : filtered.length ? <AssetTable assets={filtered} /> : <EmptyState title="No matching assets" detail="Try a broader search or clear the current severity filter." action={<button data-testid="button-clear-asset-search" onClick={() => { setSearch(''); setFilter('all'); }} className="text-xs font-bold text-primary">Clear filters</button>} />}
    </SectionCard>
  </div>;
}

function AssetDetailPage() {
  const { id = '' } = useParams<{ id: string }>(); const asset = useGetAsset(id); const controlId = asset.data?.controls?.[0]?.id ?? ''; const control = useGetControl(controlId, { query: { enabled: Boolean(controlId), queryKey: ['/api/controls', controlId] } });
  const data = asset.data;
  return <div className="animate-rise"><Link href="/assets" data-testid="link-back-assets" className="mb-5 inline-flex items-center gap-1 text-[11px] font-bold text-muted-foreground hover:text-foreground">← Asset inventory</Link>{asset.isLoading ? <><Skeleton className="h-20" /><div className="mt-4 grid gap-4 lg:grid-cols-2"><Skeleton className="h-60" /><Skeleton className="h-60" /></div></> : asset.isError || !data ? <ErrorState retry={() => asset.refetch()} detail="This asset could not be found in the current model." /> : <><PageHeader eyebrow={`Asset detail · ${data.assetType}`} title={data.name} detail={`${data.service} · ${data.businessUnit} · Owner ${data.owner}`} action={<span className={`rounded-md px-2.5 py-1.5 text-[10px] font-bold uppercase ${severityClass(data.severity)}`}>{data.severity} exposure</span>} /><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><MetricCard testId="metric-asset-eal" label="Asset EAL" value={money(data.eal)} detail="Expected annual loss" accent /><MetricCard testId="metric-asset-likelihood" label="Likelihood" value={likelihoodPct(data.likelihood)} detail="Modeled probability" /><MetricCard testId="metric-asset-control" label="Control efficacy" value={pct(data.controlEffectiveness)} detail={data.environment} /><MetricCard testId="metric-asset-criticality" label="Criticality" value={`${data.criticality}/100`} detail={data.dataSensitivity} /><MetricCard testId="metric-asset-vulns" label="Open vulnerabilities" value={`${data.vulnerabilities.length}`} detail="Mapped findings" /></div><div className="mt-4 grid gap-4 lg:grid-cols-[1.1fr_.9fr]"><SectionCard title="Financial contribution" eyebrow="Why this asset matters"><div className="space-y-4">{data.contributions.map(item => <div key={item.label}><div className="flex justify-between text-xs"><span className="font-bold">{item.label}</span><span className="font-mono-ui">{item.value.toFixed(1)} pts</span></div><div className="mt-1.5 h-1.5 overflow-hidden rounded bg-secondary"><div className={`h-full ${item.direction === 'negative' ? 'bg-emerald-600' : 'bg-accent'}`} style={{ width: `${Math.min(Math.abs(item.value) * 8, 100)}%` }} /></div></div>)}</div><div className="mt-5 rounded-lg bg-secondary/60 p-3 text-[11px] leading-5 text-muted-foreground"><strong className="text-foreground">Dependencies:</strong> {data.dependencies.join(' · ')}</div></SectionCard><SectionCard title="Control posture" eyebrow="First mapped control">{control.data ? <ControlMini control={control.data} /> : <div className="space-y-3">{data.controls.slice(0, 3).map(item => <ControlMini key={item.id} control={item} />)}</div>}</SectionCard></div><SectionCard title="Recommended moves" eyebrow="Actions that change the number" className="mt-4"><div className="grid gap-3 md:grid-cols-2">{data.recommendations.map(action => <div key={action.id} className="flex items-start gap-3 rounded-lg border border-border p-3"><div className="mt-0.5 rounded-md bg-accent/20 p-2 text-accent-foreground"><Target size={15} /></div><div className="min-w-0 flex-1"><div className="text-xs font-bold">{action.name}</div><p className="mt-1 text-[11px] leading-4 text-muted-foreground">{action.description}</p><div className="mt-3 flex items-center gap-3 text-[10px]"><span className="font-mono-ui">{moneyFull(action.cost)}</span><span className="text-emerald-700">↓ {money(action.reduction)} EAL</span><span className="text-muted-foreground">{action.days} days</span></div></div></div>)}</div></SectionCard></>}</div>;
}

function ControlMini({ control }: { control: Control }) {
  return <div className="rounded-lg border border-border p-3"><div className="flex justify-between gap-2"><div className="text-xs font-bold">{control.name}</div><span className="text-[10px] font-bold text-emerald-700">{control.status}</span></div><div className="mt-3 grid grid-cols-4 gap-2">{[['Coverage', control.coverage], ['Config', control.configuration], ['Comply', control.compliance], ['Telemetry', control.telemetry]].map(([label, value]) => <div key={label as string}><div className="text-[9px] text-muted-foreground">{label}</div><div className="mt-1 font-mono-ui text-[11px]">{pct(value as number)}</div></div>)}</div></div>;
}

function VulnerabilitiesPage() {
  const vulns = useGetVulnerabilities(); const [search, setSearch] = useState(''); const [status, setStatus] = useState('all');
  const filtered = (vulns.data ?? []).filter(v => `${v.cve} ${v.title}`.toLowerCase().includes(search.toLowerCase())).filter(v => status === 'all' || v.remediationStatus.toLowerCase().includes(status));
  return <div className="animate-rise"><PageHeader eyebrow="Vulnerability intelligence" title="Findings with a financial shadow." detail="Prioritize remediation by modeled EAL contribution, exploitability, and the assets carrying the exposure." action={<Link href="/simulations" data-testid="link-vulns-to-simulations" className="flex items-center gap-2 rounded-lg border border-input bg-card px-3 py-2.5 text-xs font-bold hover:border-primary"><Target size={14} /> Test remediation</Link>} /><SectionCard title="Vulnerability register" eyebrow={`${vulns.data?.length ?? 0} findings · sorted by modeled contribution`}><div className="mb-4 flex flex-col gap-2 sm:flex-row"><label className="relative flex-1"><Search size={14} className="absolute left-3 top-2.5 text-muted-foreground" /><input data-testid="input-search-vulnerabilities" value={search} onChange={e => setSearch(e.target.value)} placeholder="Search CVE or vulnerability title" className="w-full rounded-lg border border-input bg-background py-2 pl-9 pr-3 text-xs outline-none focus:border-primary" /></label><select data-testid="select-vulnerability-status" value={status} onChange={e => setStatus(e.target.value)} className="rounded-lg border border-input bg-background px-3 py-2 text-xs outline-none"><option value="all">All statuses</option><option value="open">Open</option><option value="progress">In progress</option><option value="resolved">Resolved</option></select></div>{vulns.isLoading ? <Skeleton className="h-80" /> : vulns.isError ? <ErrorState retry={() => vulns.refetch()} /> : filtered.length ? <div className="overflow-x-auto"><table className="w-full min-w-[760px] text-left"><thead><tr className="border-b border-border text-[9px] font-bold uppercase tracking-wider text-muted-foreground"><th className="pb-2">Finding</th><th className="pb-2">CVSS</th><th className="pb-2">Exploit signal</th><th className="pb-2">Assets</th><th className="pb-2">EAL contribution</th><th className="pb-2">Status</th><th /></tr></thead><tbody>{filtered.map(v => <tr key={v.id} data-testid={`row-vulnerability-${v.id}`} className="border-b border-border/70 text-xs last:border-0"><td className="py-3"><Link href={`/vulnerabilities/${v.id}`} data-testid={`link-vulnerability-${v.id}`} className="group flex items-start gap-2 hover:text-primary"><span className={`mt-0.5 h-2 w-2 rounded-full ${v.activelyExploited ? 'bg-destructive' : v.exploitAvailable ? 'bg-accent' : 'bg-muted-foreground'}`} /><span><span className="block font-bold">{v.cve}</span><span className="mt-0.5 block max-w-[300px] text-[10px] text-muted-foreground">{v.title}</span></span></Link></td><td className="py-3"><span className={`rounded px-1.5 py-1 text-[10px] font-bold ${v.cvss >= 9 ? 'bg-destructive/10 text-destructive' : 'bg-accent/20 text-accent-foreground'}`}>{v.cvss.toFixed(1)}</span></td><td className="py-3">{v.activelyExploited ? <span className="font-bold text-destructive">Active exploitation</span> : v.exploitAvailable ? <span className="font-bold text-accent-foreground">Exploit available</span> : <span className="text-muted-foreground">No known exploit</span>}</td><td className="py-3 font-mono-ui">{v.affectedAssets}</td><td className="py-3 font-mono-ui">{money(v.ealContribution)}</td><td className="py-3"><span className={`rounded-full px-2 py-1 text-[9px] font-bold ${v.remediationStatus.toLowerCase().includes('open') ? 'bg-destructive/10 text-destructive' : 'bg-secondary text-muted-foreground'}`}>{v.remediationStatus}</span></td><td className="py-3 text-right"><ChevronRight size={14} className="text-muted-foreground" /></td></tr>)}</tbody></table></div> : <EmptyState title="No findings match" detail="Change the search or status filter to see more of the register." />}</SectionCard></div>;
}

function VulnerabilityDetailPage() {
  const { id = '' } = useParams<{ id: string }>(); const vuln = useGetVulnerability(id); const data = vuln.data;
  return <div className="animate-rise"><Link href="/vulnerabilities" data-testid="link-back-vulnerabilities" className="mb-5 inline-flex items-center gap-1 text-[11px] font-bold text-muted-foreground hover:text-foreground">← Vulnerability register</Link>{vuln.isLoading ? <Skeleton className="h-72" /> : vuln.isError || !data ? <ErrorState retry={() => vuln.refetch()} detail="This vulnerability is not present in the current model." /> : <><PageHeader eyebrow={`Finding detail · ${data.cve}`} title={data.title} detail={`${data.cve} · ${data.affectedAssets} affected assets · ${data.ageDays} days old`} action={<span className={`rounded-md px-2.5 py-1.5 text-[10px] font-bold uppercase ${severityClass(data.severity)}`}>{data.severity}</span>} /><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><MetricCard testId="metric-vuln-cvss" label="CVSS" value={data.cvss.toFixed(1)} detail="Base severity score" accent /><MetricCard testId="metric-vuln-eal" label="EAL contribution" value={money(data.ealContribution)} detail="Modeled annual loss" /><MetricCard testId="metric-vuln-assets" label="Affected assets" value={`${data.affectedAssets}`} detail="Across mapped services" /><MetricCard testId="metric-vuln-age" label="Finding age" value={`${data.ageDays}d`} detail="Since first observed" /><MetricCard testId="metric-vuln-status" label="Remediation" value={data.remediationStatus} detail={data.activelyExploited ? 'Active exploitation signal' : 'No active exploitation'} /></div><div className="mt-4 grid gap-4 lg:grid-cols-2"><SectionCard title="Blast radius" eyebrow="Mapped scope"><div className="space-y-4"><div><div className="mb-2 text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Affected services</div><div className="flex flex-wrap gap-2">{data.affectedServices.map(item => <span key={item} className="rounded-md bg-secondary px-2 py-1.5 text-[11px] font-bold">{item}</span>)}</div></div><div><div className="mb-2 text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Business units</div><div className="flex flex-wrap gap-2">{data.affectedBusinessUnits.map(item => <span key={item} className="rounded-md border border-border px-2 py-1.5 text-[11px]">{item}</span>)}</div></div></div></SectionCard><SectionCard title="Why now" eyebrow="Analyst recommendation"><div className="rounded-lg border border-accent/25 bg-accent/10 p-4 text-sm leading-6">{data.recommendation}</div><div className="mt-4 flex items-start gap-2 text-[10px] leading-4 text-muted-foreground"><Info size={13} className="mt-0.5 shrink-0" />Remediation priority is modeled from CVSS, exploit signals, asset criticality, and control efficacy.</div></SectionCard></div><SectionCard title="Mapped controls" eyebrow="Coverage against this finding" className="mt-4"><div className="grid gap-3 md:grid-cols-2">{data.controls.map(control => <ControlMini key={control.id} control={control} />)}</div></SectionCard></>}</div>;
}

function SimulationsPage() {
  const controls = useGetControls(); const simulate = useSimulateScenario(); const [selected, setSelected] = useState<string[]>([]); const [mfa, setMfa] = useState(78); const [delay, setDelay] = useState(14); const [result, setResult] = useState<ScenarioResult | null>(null);
  const toggle = (id: string) => setSelected(current => current.includes(id) ? current.filter(item => item !== id) : [...current, id]);
  const run = () => {
    const actionIds = selected.map(id => ({ 'ctrl-mfa': 'mfa', 'ctrl-vm': 'patch', 'ctrl-edr': 'edr', 'ctrl-seg': 'segment', 'ctrl-backup': 'backup' }[id] ?? id));
    simulate.mutate({ data: { actionIds, mfaCoverage: mfa, delayDays: delay } }, { onSuccess: setResult });
  };
  return <div className="animate-rise"><PageHeader eyebrow="Decision lab · what-if" title="Change the inputs. See the exposure move." detail="Build a mitigation package from available actions, then compare projected EAL, cost, and return on security investment before committing budget." action={<span className="flex items-center gap-2 text-[10px] text-muted-foreground"><Sparkles size={13} className="text-accent" /> Scenario engine ready</span>} /><div className="grid gap-4 lg:grid-cols-[.86fr_1.14fr]"><SectionCard title="Scenario inputs" eyebrow="Choose the intervention"><div className="space-y-5"><div><div className="mb-2 flex justify-between text-xs"><span className="font-bold">Mitigation actions</span><span className="font-mono-ui text-muted-foreground">{selected.length} selected</span></div>{controls.data?.slice(0, 5).map(control => <label key={control.id} className={`mb-2 flex cursor-pointer items-center gap-3 rounded-lg border p-3 ${selected.includes(control.id) ? 'border-primary bg-primary/5' : 'border-border hover:border-primary/40'}`}><input data-testid={`checkbox-scenario-${control.id}`} type="checkbox" checked={selected.includes(control.id)} onChange={() => toggle(control.id)} className="accent-primary" /><span className="flex-1"><span className="block text-xs font-bold">{control.name}</span><span className="mt-0.5 block text-[10px] text-muted-foreground">{control.category} · current efficacy {pct(control.effectiveness)}</span></span>{selected.includes(control.id) && <Check size={15} className="text-primary" />}</label>)}</div><label className="block"><div className="mb-2 flex justify-between text-xs"><span className="font-bold">MFA coverage target</span><span className="font-mono-ui">{mfa}%</span></div><input data-testid="input-scenario-mfa" type="range" min="50" max="100" value={mfa} onChange={e => setMfa(Number(e.target.value))} className="w-full accent-primary" /></label><label className="block"><div className="mb-2 flex justify-between text-xs"><span className="font-bold">Remediation delay</span><span className="font-mono-ui">{delay} days</span></div><input data-testid="input-scenario-delay" type="range" min="0" max="60" value={delay} onChange={e => setDelay(Number(e.target.value))} className="w-full accent-primary" /></label><button data-testid="button-run-scenario" onClick={run} disabled={simulate.isPending} className="flex w-full items-center justify-center gap-2 rounded-lg bg-primary px-3 py-3 text-xs font-bold text-primary-foreground hover:bg-primary/90 disabled:opacity-60">{simulate.isPending ? <Loader2 size={14} className="animate-spin" /> : <Play size={14} />} {simulate.isPending ? 'Modeling exposure…' : 'Run scenario'}</button></div></SectionCard><SectionCard title="Projected outcome" eyebrow="Baseline vs intervention">{result ? <><div className="grid gap-3 sm:grid-cols-3"><MetricCard testId="metric-scenario-baseline" label="Baseline EAL" value={money(result.baselineEal)} detail="Current modeled state" /><MetricCard testId="metric-scenario-projected" label="Projected EAL" value={money(result.projectedEal)} detail="With selected package" accent /><MetricCard testId="metric-scenario-rosi" label="ROSI" value={`${result.rosi.toFixed(1)}%`} detail={`${moneyFull(result.cost)} modeled cost`} /></div><div className="mt-6"><div className="mb-2 flex items-center justify-between"><span className="text-xs font-bold">Exposure curve</span><span className="text-[10px] text-emerald-700">↓ {money(result.reduction)} reduction</span></div><Sparkline points={result.exposureCurve.map((point: CurvePoint) => point.value)} color="hsl(var(--chart-2))" /><div className="mt-2 flex justify-between text-[9px] text-muted-foreground">{result.exposureCurve.slice(0, 4).map((point: CurvePoint) => <span key={point.label}>{point.label}</span>)}</div></div><div className="mt-5 flex items-start gap-2 rounded-lg bg-emerald-600/10 p-3 text-[11px] leading-5 text-emerald-800"><CircleCheck size={15} className="mt-0.5 shrink-0" />This package reduces modeled annual exposure by {money(result.reduction)} for an estimated {moneyFull(result.cost)} investment.</div></> : <div className="flex min-h-[365px] flex-col items-center justify-center text-center"><div className="rounded-xl bg-secondary p-4 text-primary"><LineChart size={26} /></div><h3 className="mt-4 text-sm font-bold">No scenario run yet</h3><p className="mt-1 max-w-xs text-xs leading-5 text-muted-foreground">Select one or more actions to produce a modeled exposure curve and return profile.</p></div>}</SectionCard></div><div className="mt-5 flex items-start gap-2 text-[10px] leading-4 text-muted-foreground"><Info size={13} className="mt-0.5 shrink-0" />Scenario outputs are synthetic estimates. They are directional and should be paired with implementation cost, delivery capacity, and risk appetite review.</div></div>;
}

function OptimizationPage() {
  const optimize = useOptimizeBudget(); const [budget, setBudget] = useState(1250000); const [result, setResult] = useState<any>(null); const run = () => optimize.mutate({ data: { budget } }, { onSuccess: setResult });
  return <div className="animate-rise"><PageHeader eyebrow="Decision lab · capital allocation" title="Put the next rupee where it matters." detail="Optimize a finite security budget against modeled EAL reduction. The recommendation is explicit, inspectable, and easy to challenge." action={<button data-testid="button-run-optimization-header" onClick={run} className="flex items-center gap-2 rounded-lg bg-primary px-3 py-2.5 text-xs font-bold text-primary-foreground hover:bg-primary/90"><Sparkles size={14} /> Optimize now</button>} /><div className="grid gap-4 lg:grid-cols-[.75fr_1.25fr]"><SectionCard title="Budget envelope" eyebrow="Investment constraint"><div className="flex items-end gap-2"><span className="font-mono-ui text-3xl">{money(budget)}</span><span className="mb-1 text-xs text-muted-foreground">available</span></div><input data-testid="input-optimization-budget" type="range" min="250000" max="5000000" step="50000" value={budget} onChange={e => setBudget(Number(e.target.value))} className="mt-6 w-full accent-primary" /><div className="mt-2 flex justify-between text-[9px] text-muted-foreground"><span>₹2.5 L</span><span>₹50 L</span></div><div className="mt-7 rounded-lg border border-border bg-secondary/40 p-3 text-[11px] leading-5 text-muted-foreground"><div className="mb-1 flex items-center gap-2 font-bold text-foreground"><BriefcaseBusiness size={14} className="text-accent-foreground" /> Optimization objective</div>Maximize modeled EAL reduction while respecting the budget envelope and action delivery constraints.</div><button data-testid="button-run-optimization" onClick={run} disabled={optimize.isPending} className="mt-5 flex w-full items-center justify-center gap-2 rounded-lg bg-primary px-3 py-3 text-xs font-bold text-primary-foreground disabled:opacity-60">{optimize.isPending ? <Loader2 size={14} className="animate-spin" /> : <BarChart3 size={14} />} {optimize.isPending ? 'Optimizing portfolio…' : 'Run budget optimization'}</button></SectionCard><SectionCard title="Recommended portfolio" eyebrow="ROSI curve · modeled outcome">{result ? <><div className="grid gap-3 sm:grid-cols-3"><MetricCard testId="metric-optimization-cost" label="Allocated" value={moneyFull(result.totalCost)} detail={`of ${moneyFull(result.budget)} budget`} /><MetricCard testId="metric-optimization-reduction" label="EAL reduction" value={money(result.reduction)} detail="Modeled annual exposure" accent /><MetricCard testId="metric-optimization-remaining" label="Remaining" value={moneyFull(result.remainingBudget)} detail="Unallocated reserve" /></div><div className="mt-5"><div className="mb-2 flex justify-between text-xs"><span className="font-bold">Efficient frontier</span><span className="font-mono-ui text-muted-foreground">reduction / spend</span></div><Sparkline points={result.curve.map((point: CurvePoint) => point.value)} color="hsl(var(--chart-1))" /></div><div className="mt-5 space-y-2">{result.actions.map((action: any, i: number) => <div key={action.id} className="flex items-center gap-3 rounded-lg border border-border p-3"><div className="font-mono-ui text-[10px] text-muted-foreground">0{i + 1}</div><div className="flex-1"><div className="text-xs font-bold">{action.name}</div><div className="mt-1 text-[10px] text-muted-foreground">{action.days} days · {action.category}</div></div><div className="text-right"><div className="font-mono-ui text-xs">{moneyFull(action.cost)}</div><div className="text-[10px] font-bold text-emerald-700">↓ {money(action.reduction)}</div></div></div>)}</div></> : <div className="flex min-h-[390px] flex-col items-center justify-center text-center"><div className="rounded-xl bg-secondary p-4 text-primary"><CircleDollarSign size={26} /></div><h3 className="mt-4 text-sm font-bold">Portfolio not optimized</h3><p className="mt-1 max-w-xs text-xs leading-5 text-muted-foreground">Set an envelope and run the optimizer to see the recommended action sequence.</p></div>}</SectionCard></div><div className="mt-5 flex items-start gap-2 text-[10px] leading-4 text-muted-foreground"><Info size={13} className="mt-0.5 shrink-0" />ROSI is a modeled return, not a realized financial return. Investment recommendations should be reviewed against business delivery constraints.</div></div>;
}

function CompliancePage() {
  const frameworks = useGetCompliance(); const [selected, setSelected] = useState<string | null>(null); const detail = useGetComplianceFramework(selected ?? '', { query: { enabled: Boolean(selected), queryKey: ['/api/compliance', selected] } }); const list = selected && detail.data ? [detail.data] : frameworks.data;
  return <div className="animate-rise"><PageHeader eyebrow="Assurance" title="Posture you can defend." detail="Connect control evidence to framework requirements, then make the gaps visible enough to fund." action={<div className="flex items-center gap-2 text-[10px] text-muted-foreground"><FileCheck2 size={14} /> Evidence refresh · 14 min ago</div>} /><div className="grid gap-4 lg:grid-cols-[.75fr_1.25fr]"><SectionCard title="Framework posture" eyebrow="Current coverage">{frameworks.isLoading ? <Skeleton className="h-72" /> : frameworks.data?.length ? <div className="space-y-3">{frameworks.data.map(framework => <button data-testid={`button-framework-${framework.id}`} key={framework.id} onClick={() => setSelected(framework.id)} className={`w-full rounded-lg border p-3 text-left ${selected === framework.id ? 'border-primary bg-primary/5' : 'border-border hover:border-primary/40'}`}><div className="flex items-start justify-between gap-3"><div><div className="text-xs font-bold">{framework.name}</div><div className="mt-1 text-[10px] text-muted-foreground">{framework.version} · {framework.requirements.length} requirements</div></div><span className="font-mono-ui text-sm">{pct(framework.posture)}</span></div><div className="mt-3 h-1.5 overflow-hidden rounded bg-secondary"><div className="h-full bg-accent" style={{ width: `${framework.posture}%` }} /></div><div className="mt-2 text-[10px] text-destructive">{framework.gaps} open gaps</div></button>)}</div> : <EmptyState title="No frameworks connected" detail="Framework posture will appear after evidence sync." />}</SectionCard><SectionCard title={selected ? 'Requirement detail' : 'Open gaps across frameworks'} eyebrow={selected ? 'Selected framework' : 'Focus area'}>{selected && detail.isLoading ? <Skeleton className="h-72" /> : list?.length ? <div className="space-y-3">{list.flatMap((framework: ComplianceFramework) => framework.requirements.slice(0, selected ? framework.requirements.length : 4).map(requirement => <div key={`${framework.id}-${requirement.code}`} className="rounded-lg border border-border p-3"><div className="flex items-start justify-between gap-3"><div><div className="font-mono-ui text-[10px] text-muted-foreground">{requirement.code}</div><div className="mt-1 text-xs font-bold">{requirement.title}</div></div><span className={`rounded-full px-2 py-1 text-[9px] font-bold ${requirement.status.toLowerCase().includes('pass') || requirement.status.toLowerCase().includes('compliant') ? 'bg-emerald-600/10 text-emerald-700' : 'bg-destructive/10 text-destructive'}`}>{requirement.status}</span></div><div className="mt-3 grid gap-2 text-[10px] sm:grid-cols-2"><div><span className="text-muted-foreground">Control</span><div className="mt-1 font-bold">{requirement.control}</div></div><div><span className="text-muted-foreground">Last verified</span><div className="mt-1 font-mono-ui">{requirement.lastVerified}</div></div></div>{requirement.gap && <div className="mt-3 rounded-md bg-destructive/5 p-2 text-[10px] leading-4 text-muted-foreground"><strong className="text-destructive">Gap:</strong> {requirement.gap}</div>}</div>))}</div> : <EmptyState title="No requirement data" detail="Select a framework or refresh evidence." />}</SectionCard></div>{selected && <button data-testid="button-clear-framework" onClick={() => setSelected(null)} className="mt-4 inline-flex items-center gap-2 text-xs font-bold text-primary"><X size={14} /> Show all frameworks</button>}</div>;
}

function CopilotPage() {
  const ask = useAskCopilot(); const [question, setQuestion] = useState('What should I fund first to reduce enterprise EAL?'); const [answer, setAnswer] = useState<any>(null); const prompts = ['What should I fund first to reduce enterprise EAL?', 'Explain the largest risk driver in plain language.', 'Which critical asset deserves an executive review?'];
  const submit = (event: React.FormEvent) => { event.preventDefault(); if (!question.trim()) return; ask.mutate({ data: { question } }, { onSuccess: setAnswer }); };
  return <div className="animate-rise"><PageHeader eyebrow="Grounded intelligence" title="Ask the model, not a generic chatbot." detail="CyberRisk Copilot answers from NovaBank's modeled exposure, telemetry, control posture, and optimization outputs — with citations you can take into the room." action={<span className="flex items-center gap-2 text-[10px] text-emerald-700"><span className="h-1.5 w-1.5 rounded-full bg-emerald-600" /> Grounded on API data</span>} /><div className="grid gap-4 lg:grid-cols-[.72fr_1.28fr]"><SectionCard title="Start with a decision" eyebrow="Suggested prompts"><div className="space-y-2">{prompts.map(prompt => <button data-testid={`button-prompt-${prompts.indexOf(prompt)}`} key={prompt} onClick={() => setQuestion(prompt)} className={`w-full rounded-lg border p-3 text-left text-xs leading-5 ${question === prompt ? 'border-primary bg-primary/5 font-bold' : 'border-border hover:border-primary/40'}`}>{prompt}<ChevronRight size={14} className="float-right mt-0.5 text-muted-foreground" /></button>)}</div><div className="mt-6 rounded-lg bg-secondary/55 p-3 text-[10px] leading-4 text-muted-foreground"><div className="mb-1 flex items-center gap-2 font-bold text-foreground"><LockKeyhole size={13} className="text-accent-foreground" /> Grounding boundary</div>Copilot does not invent telemetry. If the API has no evidence, it will say so.</div></SectionCard><SectionCard title="Executive answer" eyebrow={answer?.tool ? `Source · ${answer.tool}` : 'Conversation'}><div className="flex min-h-[370px] flex-col">{answer ? <><div className="flex gap-3"><div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-primary text-primary-foreground"><Bot size={16} /></div><div className="rounded-lg border border-border bg-secondary/50 p-4 text-sm leading-6">{answer.answer}</div></div><div className="mt-auto border-t border-border pt-4"><div className="mb-2 text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Grounding citations</div><div className="flex flex-wrap gap-2">{answer.citations.map((citation: string) => <span key={citation} className="rounded-md bg-secondary px-2 py-1 text-[10px] font-mono-ui">{citation}</span>)}</div></div></> : <div className="flex flex-1 flex-col items-center justify-center text-center"><div className="rounded-xl bg-secondary p-4 text-primary"><Bot size={28} /></div><h3 className="mt-4 text-sm font-bold">Your risk brief starts here</h3><p className="mt-1 max-w-xs text-xs leading-5 text-muted-foreground">Ask for a funding recommendation, driver explanation, or executive-ready framing.</p></div>}<form onSubmit={submit} className="mt-4 flex gap-2"><input data-testid="input-copilot-question" value={question} onChange={e => setQuestion(e.target.value)} placeholder="Ask about the model…" className="min-w-0 flex-1 rounded-lg border border-input bg-background px-3 py-2.5 text-xs outline-none focus:border-primary" /><button data-testid="button-ask-copilot" disabled={ask.isPending || !question.trim()} className="flex items-center gap-2 rounded-lg bg-primary px-3 py-2.5 text-xs font-bold text-primary-foreground disabled:opacity-60">{ask.isPending ? <Loader2 size={14} className="animate-spin" /> : <Send size={14} />} Ask</button></form></div></SectionCard></div></div>;
}

function DataSourcesPage() {
  const ingest = useIngestEvent(); const qc = useQueryClient(); const [last, setLast] = useState<any>(null); const sources = [{ name: 'CloudTrail + IAM', type: 'Identity telemetry', status: 'Healthy', events: '18.4K', sync: '2 min ago' }, { name: 'Nessus Enterprise', type: 'Vulnerability findings', status: 'Healthy', events: '4,218', sync: '9 min ago' }, { name: 'ServiceNow CMDB', type: 'Asset context', status: 'Delayed', events: '1,902', sync: '34 min ago' }, { name: 'CrowdStrike Falcon', type: 'Endpoint telemetry', status: 'Healthy', events: '62.7K', sync: '4 min ago' }];
  const run = (type: string, severity: string) => ingest.mutate({ data: { type, severity } }, { onSuccess: result => { setLast(result); qc.invalidateQueries(); } });
  return <div className="animate-rise"><PageHeader eyebrow="Telemetry fabric" title="Know what the model is hearing." detail="Connector health and simulated event controls for the NovaBank demonstration environment." action={<button data-testid="button-refresh-sources" onClick={() => qc.invalidateQueries()} className="flex items-center gap-2 rounded-lg border border-input bg-card px-3 py-2.5 text-xs font-bold hover:border-primary"><RefreshCw size={14} /> Refresh status</button>} /><SectionCard title="Connector status" eyebrow="Last heartbeat by source"><div className="grid gap-3 md:grid-cols-2">{sources.map(source => <div key={source.name} className="rounded-lg border border-border p-4"><div className="flex items-start justify-between"><div><div className="text-xs font-bold">{source.name}</div><div className="mt-1 text-[10px] text-muted-foreground">{source.type}</div></div><span className={`flex items-center gap-1.5 text-[10px] font-bold ${source.status === 'Healthy' ? 'text-emerald-700' : 'text-accent-foreground'}`}><span className={`h-1.5 w-1.5 rounded-full ${source.status === 'Healthy' ? 'bg-emerald-600' : 'bg-accent'}`} />{source.status}</span></div><div className="mt-5 flex justify-between text-[10px]"><span><span className="font-mono-ui">{source.events}</span> events</span><span className="text-muted-foreground">{source.sync}</span></div></div>)}</div></SectionCard><div className="mt-4 grid gap-4 lg:grid-cols-[.9fr_1.1fr]"><SectionCard title="Event ingestion controls" eyebrow="Synthetic input"><div className="space-y-2"><button data-testid="button-ingest-critical" onClick={() => run('critical_vulnerability', 'critical')} disabled={ingest.isPending} className="flex w-full items-center gap-3 rounded-lg border border-border p-3 text-left hover:border-destructive/50"><div className="rounded-md bg-destructive/10 p-2 text-destructive"><TriangleAlert size={15} /></div><div className="flex-1"><div className="text-xs font-bold">Critical vulnerability discovered</div><div className="mt-1 text-[10px] text-muted-foreground">Injects a high-severity finding into the Payments API.</div></div><Plus size={15} className="text-muted-foreground" /></button><button data-testid="button-ingest-control-improvement" onClick={() => run('control_improvement', 'medium')} disabled={ingest.isPending} className="flex w-full items-center gap-3 rounded-lg border border-border p-3 text-left hover:border-emerald-600/50"><div className="rounded-md bg-emerald-600/10 p-2 text-emerald-700"><ShieldCheck size={15} /></div><div className="flex-1"><div className="text-xs font-bold">Control improvement verified</div><div className="mt-1 text-[10px] text-muted-foreground">Injects improved MFA coverage and recalculates exposure.</div></div><Plus size={15} className="text-muted-foreground" /></button></div></SectionCard><SectionCard title="Latest ingestion result" eyebrow="Model feedback">{last ? <div><div className="rounded-lg border border-accent/25 bg-accent/10 p-4"><div className="flex items-center gap-2 text-xs font-bold"><CircleCheck size={15} className="text-emerald-700" /> {last.message}</div><div className="mt-4 grid grid-cols-3 gap-3"><div><div className="text-[9px] text-muted-foreground">Before</div><div className="mt-1 font-mono-ui text-xs">{moneyFull(last.ealBefore)}</div></div><div><div className="text-[9px] text-muted-foreground">After</div><div className="mt-1 font-mono-ui text-xs">{moneyFull(last.ealAfter)}</div></div><div><div className="text-[9px] text-muted-foreground">Delta</div><div className="mt-1 font-mono-ui text-xs">{moneyFull(last.delta)}</div></div></div></div><div className="mt-4 space-y-2">{last.timeline.map((event: string) => <div key={event} className="flex items-center gap-2 text-[10px] text-muted-foreground"><span className="h-1.5 w-1.5 rounded-full bg-accent" />{event}</div>)}</div></div> : <EmptyState title="No event ingested" detail="Use a control above to see the full vulnerability → risk → exposure → driver chain." />}</SectionCard></div><div className="mt-5 flex items-start gap-2 rounded-lg border border-border bg-secondary/35 px-3 py-2.5 text-[10px] leading-4 text-muted-foreground"><Info size={13} className="mt-0.5 shrink-0" /><span><strong className="text-foreground">Demo environment:</strong> Connectors and events are simulated. Ingestion invalidates the live overview, driver, and trend queries so the UI follows the model.</span></div></div>;
}

function AppRouter() {
  const [location] = useLocation();
  return <AppShell><ErrorBoundary resetKey={location}><Switch>
    <Route path="/" component={OverviewPage} />
    <Route path="/risk" component={RiskPage} />
    <Route path="/assets" component={AssetsPage} />
    <Route path="/assets/:id" component={AssetDetailPage} />
    <Route path="/vulnerabilities" component={VulnerabilitiesPage} />
    <Route path="/vulnerabilities/:id" component={VulnerabilityDetailPage} />
    <Route path="/simulations" component={SimulationsPage} />
    <Route path="/optimization" component={OptimizationPage} />
    <Route path="/compliance" component={CompliancePage} />
    <Route path="/copilot" component={CopilotPage} />
    <Route path="/data-sources" component={DataSourcesPage} />
    <Route component={() => <EmptyState title="Page not found" detail="The requested cockpit view does not exist." action={<Link href="/" data-testid="link-back-home" className="text-xs font-bold text-primary">Return to overview</Link>} />} />
  </Switch></ErrorBoundary></AppShell>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><AppRouter /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;